// --- Required n8n Variables check ---
if (!$vars.DRESS_REMINDER_INTERVALS || !$vars.HOME_COORDS) {
  throw new Error('Missing n8n Variables: DRESS_REMINDER_INTERVALS, HOME_COORDS. Set them in Settings → Variables.');
}
const HOME_COORDS = $vars.HOME_COORDS || '';

// Find reminders that are due within the last 10-minute window
const now = new Date();
const windowMinAgo = new Date(now.getTime() - 10 * 60 * 1000);
const fourAM = new Date(now);
fourAM.setHours(4, 0, 0, 0);
const items = $input.all();
const dueReminders = [];
const terminalStates = ['cancelled', 'skipped', 'arrived', 'expired', 'departed'];
const today = DateTime.now().setZone('Europe/Bucharest').toISODate(); // YYYY-MM-DD, timezone-aware

// Configurable dressed reminder intervals (minutes before departure, descending order)
const ALL_DRESS_INTERVALS = $vars.DRESS_REMINDER_INTERVALS.split(',').map(s => s.trim()).filter(Boolean).map(Number).filter(n => !isNaN(n)); // e.g. "90,60,30,15" → [90, 60, 30, 15]

for (const item of items) {
  const row = item.json;

  // Skip terminal states
  if (terminalStates.includes(row.current_state)) continue;

  // Skip past events (end_time < now)
  if (new Date(row.end_time) < now) continue;

  // Skip if not today
  if (row.plan_date !== today) continue;

  // Parse already-sent reminders
  const sent = (row.reminders_sent || '').split(',').map(s => s.trim());

  // Determine effective departure time (traffic-updated if available)
  const effectiveDep = row.traffic_updated_departure || row.departure_time;
  const depTime = new Date(effectiveDep);

  // Build standard reminder checks (non-dressed)
  const reminderChecks = [
    { type: 'remind_60', time: new Date(depTime.getTime() - 60 * 60 * 1000), channels: ['push'] },
    { type: 'remind_30', time: new Date(depTime.getTime() - 30 * 60 * 1000), channels: ['push'] },
    { type: 'remind_15', time: new Date(depTime.getTime() - 15 * 60 * 1000), channels: ['push'] },
    { type: 'remind_now', time: depTime, channels: ['push', 'tts'] }
  ];

  // "Get dressed" reminders — only if user is at home for this event
  // Apply dress_cap: if event has [dress:N] or [N] tag, only fire intervals ≤ N
  const dressCap = parseInt(row.dress_cap, 10) || 0;
  const DRESS_INTERVALS = dressCap > 0
    ? ALL_DRESS_INTERVALS.filter(n => n <= dressCap)
    : ALL_DRESS_INTERVALS;

  // Walk-back origin check — must match WF4 co-location-handler.json "Select Active Event + Run State Machine"
  const isHomeOrigin = row.origin_type === 'home' || !row.origin_type
    || (row.origin_coords || '') === HOME_COORDS;
  const isAtHome = row.at_home === 'TRUE' || row.at_home === true;
  if (isAtHome && row.departure_time) {
    for (const interval of DRESS_INTERVALS) {
      const dressTime = new Date(depTime.getTime() - interval * 60 * 1000);
      // Floor: no dressed reminder before 04:00
      if (dressTime >= fourAM) {
        reminderChecks.push({
          type: `remind_dressed_${interval}`,
          time: dressTime,
          channels: ['push'],
          dress_interval: interval
        });
      }
    }
  }

  // Tentative events: skip TTS (push only)
  if (row.is_tentative === 'TRUE' || row.is_tentative === true) {
    for (const r of reminderChecks) {
      r.channels = r.channels.filter(c => c !== 'tts');
    }
  }

  for (const reminder of reminderChecks) {
    if (!sent.includes(reminder.type) && reminder.time >= windowMinAgo && reminder.time <= now) {
      dueReminders.push({
        ...row,
        reminder_type: reminder.type,
        channels: reminder.channels,
        effective_departure: effectiveDep,
        dress_interval: reminder.dress_interval || null,
        state_version: parseInt(row.state_version) || 0
      });
    }
  }
}

// Busy-day batching: if a user has >5 active events, batch dressed + 60-min reminders
const userEventCounts = {};
for (const item of items) {
  const row = item.json;
  if (!terminalStates.includes(row.current_state) && row.plan_date === today && row.is_online !== 'TRUE') {
    userEventCounts[row.user_id] = (userEventCounts[row.user_id] || 0) + 1;
  }
}

// Mark batch reminders
for (const r of dueReminders) {
  r.busy_day = (userEventCounts[r.user_id] || 0) > 5;
  r.event_count = userEventCounts[r.user_id] || 0;
}

return dueReminders.map(r => ({ json: r }));

// On busy days (>5 events), batch dressed reminders into a single digest per user.
// remind_60, remind_30, remind_15, remind_now are always sent individually (critical proximity alerts).
const allReminders = $input.all().map(i => i.json);
const batchableTypes = new Set(); // types that can be batched
// All remind_dressed_* are batchable
for (const r of allReminders) {
  if (r.reminder_type.startsWith('remind_dressed_')) {
    batchableTypes.add(r.reminder_type);
  }
}

// Separate into pass-through (critical) and batchable groups
const passThrough = [];
const batchGroups = {}; // keyed by user_id

for (const r of allReminders) {
  const isBatchable = r.busy_day && r.reminder_type.startsWith('remind_dressed_');
  if (!isBatchable) {
    passThrough.push({ json: r });
  } else {
    if (!batchGroups[r.user_id]) batchGroups[r.user_id] = [];
    batchGroups[r.user_id].push(r);
  }
}

// Create one digest item per user for batched reminders
for (const [userId, reminders] of Object.entries(batchGroups)) {
  const first = reminders[0]; // use first reminder's metadata as base
  const eventSummaries = reminders.map(r => {
    const depTime = new Date(r.effective_departure);
    const timeStr = depTime.toLocaleTimeString('en-GB', { hour: '2-digit', minute: '2-digit' });
    return `${r.title} — depart by ${timeStr}`;
  });

  passThrough.push({ json: {
    ...first,
    reminder_type: 'busy_day_digest',
    channels: ['push'],
    notification_message: `You have ${first.event_count} events today. Upcoming:\n${eventSummaries.join('\n')}`,
    notification_title: `Busy Day — ${first.event_count} Events`,
    _batched_types: reminders.map(r => r.reminder_type) // track which types were batched (for marking sent)
  }});
}

return passThrough;

const r = $json;

// Busy-day digest reminders are pre-built by Node 4a — pass through as-is
if (r.reminder_type === 'busy_day_digest') {
  return { json: r };
}

const isTentative = r.is_tentative === 'TRUE' || r.is_tentative === true;
const prefix = isTentative ? '⚠ Tentative: ' : '';

let message = '';
let title = '';
const trafficInfo = r.traffic_updated_commute_min
  ? ` (traffic: ${r.traffic_updated_commute_min} min)` : '';

// Handle interval-based dressed reminders (remind_dressed_90, remind_dressed_60, etc.)
if (r.reminder_type.startsWith('remind_dressed_')) {
  const interval = r.dress_interval;
  title = 'Get Ready';
  if (interval >= 60) {
    message = `${prefix}Time to get dressed — you leave in ${interval} min. ${r.clothing_advice || ''}`;
  } else {
    message = `${prefix}Leaving in ${interval} min — are you dressed? ${r.clothing_advice || ''}`;
  }
} else {
  switch (r.reminder_type) {
    case 'remind_60':
      title = '1 Hour Warning';
      message = `${prefix}${r.title} in ~1 hour. Depart by ${r.effective_departure}${trafficInfo}`;
      break;
    case 'remind_30':
      title = '30 Minutes';
      message = `${prefix}Leave in 30 min for ${r.title}. Mode: ${r.commute_mode}${trafficInfo}`;
      break;
    case 'remind_15':
      title = '15 Minutes!';
      message = `${prefix}Leave in 15 min for ${r.title}!`;
      break;
    case 'remind_now':
      title = 'LEAVE NOW';
      message = `${prefix}Leave NOW for ${r.title}! ${r.commute_minutes} min ${r.commute_mode}`;
      break;
  }
}

return { json: { ...r, notification_message: message, notification_title: title } };

// For batched busy-day reminders, mark ALL batched types as sent.
// For individual reminders, mark just the one type.
const r = $json;
const typesToMark = r._batched_types
  ? r._batched_types  // array of types that were batched into one digest
  : [r.reminder_type]; // single type

const currentSent = (r.reminders_sent || '').split(',').map(s => s.trim()).filter(Boolean);
const updatedSent = [...new Set([...currentSent, ...typesToMark])].join(',');

return { json: {
  event_id: r.event_id,
  reminders_sent: updatedSent,
  state_version: (r.state_version || 0) + 1,
  expected_version: r.state_version || 0
}};

const updateData = $('Mark Reminder Sent').item.json;
const freshRow = $json;
if (!freshRow || !freshRow.event_id) {
  return { json: { ...updateData, version_ok: false, reason: 'row_not_found' } };
}
const currentVersion = parseInt(freshRow.state_version) || 0;
if (currentVersion !== updateData.expected_version) {
  return { json: { ...updateData, version_ok: false, reason: 'version_mismatch',
    expected: updateData.expected_version, actual: currentVersion } };
}
return { json: { ...updateData, version_ok: true } };
